// Rule `api-v1` and `tl arch --index`: docs/generated/API-V1.json, the machine description of everything a pack may use
// (classes, what they extend, methods, signals, properties, constants). It is the contract of the kernel API version in
// engine/kernel/runner/manifest.gd (KERNEL_API, "major.minor"):
//   * a member that is removed or changed without a new major fails the rule, and the finding names the member;
//   * a member that is added needs a new minor (and a regenerated file);
//   * a method that only gains parameters with defaults at its end counts as an addition.
// Deterministic: classes and members sorted by name, no timestamps, LF endings.
import fs from "node:fs";
import path from "node:path";
import { describeClass, INDEX_SOURCES } from "./apiindex.mjs";

export const API_FILE = "docs/generated/API-V1.json";
export const VERSION_FILE = "engine/kernel/runner/manifest.gd";
const REGEN = "node devx/bin/tl.mjs arch --index";

/** KERNEL_API from manifest.gd as {text, major, minor}; null when it cannot be read. */
export function kernelApiVersion(io) {
  if (!io.has(VERSION_FILE)) return null;
  const m = /^const\s+KERNEL_API\s*:\s*String\s*=\s*"(\d+)\.(\d+)"/m.exec(io.read(VERSION_FILE));
  return m ? { text: `${m[1]}.${m[2]}`, major: Number(m[1]), minor: Number(m[2]) } : null;
}

/** The public surface, read from the GDScript sources: {ClassName: {file, extends, consts, signals, props, funcs}}. */
export function surface(io) {
  const out = {};
  const classes = io.files.filter((f) => INDEX_SOURCES.some((r) => r.test(f))).map((f) => describeClass(io.read(f), f));
  for (const c of classes.sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))) {
    const pub = (list) => list.filter((x) => !(x.name ?? x).startsWith("_"));
    out[c.name] = {
      file: c.file, extends: c.ext,
      consts: pub(c.consts),
      signals: pub(c.signals).map((s) => s.sig),
      props: pub(c.props).map((p) => p.sig),
      funcs: pub(c.funcs).map((f) => f.sig),
    };
  }
  return out;
}

export function generateApi(io, version = kernelApiVersion(io)) {
  const doc = {
    schema: "tl.api/1",
    version: version?.text ?? "0.0",
    note: `Generated by \`${REGEN}\` from the GDScript sources. Do not edit. The kernel API contract: \`tl arch\` (rule api-v1) fails when a member listed here is removed or changed without a new major version, or when a member is added without a new minor (KERNEL_API in ${VERSION_FILE}).`,
    classes: surface(io),
  };
  return JSON.stringify(doc, null, 1) + "\n";
}

const nameOf = { funcs: (s) => /func\s+([A-Za-z_]\w*)/.exec(s)?.[1] ?? s, signals: (s) => s.replace(/\(.*$/, ""), props: (s) => s.replace(/^static\s+/, "").replace(/^var\s+/, "").replace(/:.*$/, "").trim(), consts: (s) => s };
const kindWord = { funcs: "method", signals: "signal", props: "property", consts: "constant" };

/** Splits "a: int, b: Dictionary = {x: 1}" at top-level commas. */
function params(sig) {
  const open = sig.indexOf("(");
  let depth = 0, close = -1;
  for (let i = open; i < sig.length; i++) { if ("([{".includes(sig[i])) depth++; else if (")]}".includes(sig[i])) { depth--; if (depth === 0) { close = i; break; } } }
  if (open < 0 || close < 0) return null;
  const list = [];
  let cur = ""; depth = 0;
  for (const ch of sig.slice(open + 1, close)) {
    if ("([{".includes(ch)) depth++; else if (")]}".includes(ch)) depth--;
    if (ch === "," && depth === 0) { list.push(cur.trim()); cur = ""; } else cur += ch;
  }
  if (cur.trim()) list.push(cur.trim());
  return { head: sig.slice(0, open), list, tail: sig.slice(close + 1) };
}

/** True when `now` is `was` plus parameters with defaults at the end: every call written against `was` still works. */
export function extendsSignature(was, now) {
  const a = params(was), b = params(now);
  if (!a || !b || a.head !== b.head || a.tail !== b.tail || b.list.length <= a.list.length) return false;
  return a.list.every((p, i) => p === b.list[i]) && b.list.slice(a.list.length).every((p) => p.includes("="));
}

/** -> {breaking: [{key, message}], additions: [{key, message}]} between two `classes` objects. */
export function diffApi(was, now) {
  const breaking = [], additions = [];
  for (const [cn, a] of Object.entries(was)) {
    const b = now[cn];
    if (!b) { breaking.push({ key: `${cn}`, message: `class ${cn} was removed` }); continue; }
    if ((a.extends ?? "") !== (b.extends ?? "")) breaking.push({ key: `${cn}:extends`, message: `${cn} extended ${a.extends || "nothing"} and now extends ${b.extends || "nothing"}` });
    for (const kind of ["funcs", "signals", "props", "consts"]) {
      const before = new Map((a[kind] ?? []).map((s) => [nameOf[kind](s), s]));
      const after = new Map((b[kind] ?? []).map((s) => [nameOf[kind](s), s]));
      for (const [n, s] of before) {
        const t = after.get(n);
        if (t === undefined) breaking.push({ key: `${cn}.${n}`, message: `${kindWord[kind]} ${cn}.${n} was removed (it was \`${s}\`)` });
        else if (t !== s) {
          if (kind === "funcs" && extendsSignature(s, t)) additions.push({ key: `${cn}.${n}`, message: `${cn}.${n} gained parameters with defaults: \`${t}\`` });
          else breaking.push({ key: `${cn}.${n}`, message: `${kindWord[kind]} ${cn}.${n} changed: it was \`${s}\`, it is \`${t}\`` });
        }
      }
      for (const [n, s] of after) if (!before.has(n)) additions.push({ key: `${cn}.${n}`, message: `new ${kindWord[kind]} ${cn}.${n}: \`${s}\`` });
    }
  }
  for (const cn of Object.keys(now)) if (!was[cn]) additions.push({ key: cn, message: `new class ${cn}` });
  return { breaking, additions };
}

/** What stands between the checked-in description and the sources: {state, findings, text}.
 *  state: "fresh" | "missing" | "unreadable" | "broken" | "unbumped" | "backwards" | "stale". */
export function judgeApi(io) {
  const version = kernelApiVersion(io);
  const text = generateApi(io, version);
  if (!version) return { state: "unreadable", text, findings: [{ file: VERSION_FILE, key: "version", message: `cannot read \`const KERNEL_API: String = "major.minor"\` from ${VERSION_FILE}` }] };
  if (!io.has(API_FILE)) return { state: "missing", text, findings: [{ file: API_FILE, key: "missing", message: `missing; run \`${REGEN}\`` }] };
  let was;
  try { was = JSON.parse(io.read(API_FILE)); } catch (e) { return { state: "unreadable", text, findings: [{ file: API_FILE, key: "unreadable", message: `not valid JSON: ${e.message}` }] }; }
  const [oM, om] = String(was.version ?? "0.0").split(".").map(Number);
  const { breaking, additions } = diffApi(was.classes ?? {}, JSON.parse(text).classes);
  const at = (cn) => JSON.parse(text).classes[cn.split(/[.:]/)[0]]?.file ?? was.classes?.[cn.split(/[.:]/)[0]]?.file ?? API_FILE;
  if (version.major < oM || (version.major === oM && version.minor < om)) {
    return { state: "backwards", text, findings: [{ file: VERSION_FILE, key: "backwards", message: `KERNEL_API is ${version.text} but ${API_FILE} describes ${was.version}: a version never goes back` }] };
  }
  if (breaking.length && version.major === oM) {
    return { state: "broken", text, findings: breaking.map((b) => ({ file: at(b.key), key: `break:${b.key}`,
      message: `kernel API ${was.version}: ${b.message}. A v${oM} signature may not be removed or changed: restore it, or raise the major version (KERNEL_API in ${VERSION_FILE}) and run \`${REGEN}\`` })) };
  }
  if (additions.length && version.major === oM && version.minor === om) {
    return { state: "unbumped", text, findings: additions.map((a) => ({ file: at(a.key), key: `add:${a.key}`,
      message: `kernel API ${was.version}: ${a.message}. An addition needs a new minor version: set KERNEL_API to "${oM}.${om + 1}" in ${VERSION_FILE} and run \`${REGEN}\`` })) };
  }
  if (io.read(API_FILE) !== text) return { state: "stale", text, findings: [{ file: API_FILE, key: "stale", message: `stale (the sources describe ${version.text}, the file ${was.version}); run \`${REGEN}\`` }] };
  return { state: "fresh", text, findings: [] };
}

/** Rule `api-v1`. */
export function apiContract(io) {
  const j = judgeApi(io);
  const n = Object.values(JSON.parse(j.text).classes).reduce((s, c) => s + c.funcs.length + c.signals.length + c.props.length + c.consts.length, 0);
  return { findings: j.findings, notes: [`kernel API ${kernelApiVersion(io)?.text ?? "?"}: ${Object.keys(JSON.parse(j.text).classes).length} classes, ${n} members`] };
}

/** `tl arch --index`: writes the description when that is allowed. `freeze` writes it whatever changed (the first
 *  freeze of a version, or a merge of work that was done before the freeze). -> {ok, lines: [text]}. */
export function writeApi(io, root, { freeze = false } = {}) {
  const j = judgeApi(io);
  const f = path.join(root, API_FILE);
  const refuse = ["broken", "unbumped", "backwards", "unreadable"].includes(j.state) && !(freeze && j.state !== "unreadable" && kernelApiVersion(io));
  if (refuse) return { ok: false, lines: [`NOT written: ${API_FILE} (${j.state})`, ...j.findings.map((x) => `  ${x.message}`), "  (`--freeze` writes the current surface as the description of the current version: only for a surface that was never released)"] };
  fs.mkdirSync(path.dirname(f), { recursive: true });
  fs.writeFileSync(f, j.text);
  return { ok: true, lines: [`${j.state === "fresh" ? "unchanged" : "wrote"} ${API_FILE} (kernel API ${kernelApiVersion(io).text}, ${Object.keys(JSON.parse(j.text).classes).length} classes)`] };
}

/** A copy of the API sources of `root` in `dir` in which one method lost its parameter: the tree `tl arch --broken-demo` judges. */
export function makeBrokenTree(io, root, dir) {
  const keep = io.files.filter((f) => INDEX_SOURCES.some((r) => r.test(f)) || f === VERSION_FILE || f === API_FILE);
  for (const f of keep) { fs.mkdirSync(path.dirname(path.join(dir, f)), { recursive: true }); fs.copyFileSync(path.join(root, f), path.join(dir, f)); }
  const victim = "engine/kernel/api/tl_ball.gd";
  const src = fs.readFileSync(path.join(dir, victim), "utf8");
  const broken = src.replace(/^func shoot\(impulse: Vector3\) -> void:/m, "func shoot() -> void:");
  if (broken === src) throw new Error(`${victim}: \`func shoot(impulse: Vector3) -> void:\` not found`);
  fs.writeFileSync(path.join(dir, victim), broken);
  return { victim, was: "func shoot(impulse: Vector3) -> void", now: "func shoot() -> void" };
}
